function [beta_all_orth,error_all_orth,grain_volumes] = FitFieldDataWithHarmonics()

%
% Evaluate discrete harmonic expansion weights for designated field variables from MechMet or FEpX simulations.   
% Field variables may be for a loading history having specified number of output frames.  
%

%
%    Input:   (1) Base name for the microstructure file generated by MechMonics (with .mat extension)
%             (2) Base name for the grain-by-grain mesh (and mode) files generated by MechMonics (with .mat extension)
%             (3) nummodes  -- integer number of modes (between 1 and the number of modes output by MechMonics)
%             (4) numberoframes   -- interger number of frames (time steps saved) in the field data
%             (5) fieldata -- h5 output file from MechMet or FEpX simulation
%             (6) Base name for output files (VTK files for visualization and .mat files of stress distributions)
%
%     Output: (1) beta values for each mode for all frames
%             (2) error measure for between the field data and the fit with modes at each time step
%             (3) VTK files for visualization and .mat files of stress distributions
%


shafac_structure = ShapeFunctionArrays();


sfac = shafac_structure.sfac;
dndxi = shafac_structure.dndxi;
dndet = shafac_structure.dndet;
dndze = shafac_structure.dndze;
nqptv = shafac_structure.nqpt;
wtqp = shafac_structure.wtqp;
nnpe = shafac_structure.nnpe;
ncomp = 6;


mechmonicsvtkname = input('Base name of microstructure files created by MechMonics (with extension .mat): ', 's');

microstructurefilename =  [mechmonicsvtkname '_micro.mat' ];   
load(microstructurefilename);   


grains = microstructurefile.grains;
phases = microstructurefile.phases;
ngrains=max(grains);


nepermeshname = input('Base name of grain-by-grain mesh files created by MechMonics (with extension .mat): ', 's');

       
grainmeshfilename =  [nepermeshname '_' 'meshfile_gbg' ];   
load(grainmeshfilename);  

numberofmodes = input('Enter the number of modes to be used in the fitting (<= number computed in MechMonics): ', 's');
nummodes = str2num(numberofmodes);

numberoframes = input('Enter the number of frames in the .h5 dataset file to be analyzed: ', 's');
numframes = str2num(numberoframes);

framefilebasename = input('Basename (with extension .h5) of the file with coordinate, strain and orientation data: ', 's');
fieldvariablename = input('Field variable name in .h5 file: ', 's');


error_all_orth = zeros(numframes,ngrains);
beta_all_orth = zeros(numframes,ncomp,nummodes,ngrains);
field_grnave = zeros(numframes,6,ngrains);

[m n]   = size(meshfilegbg.crd);
newnumnp = n;

[m n]   = size(meshfilegbg.con);
newnumel = n;

newnp = meshfilegbg.con';
newcoords = meshfilegbg.crd;

field_modes_orth = zeros(numframes,ncomp,newnumnp);
field_data =  zeros(numframes,ncomp,newnumnp);


for igrn = 1:1:ngrains
    
igrnstr = string(igrn);   
message = [' Working on Grain Number: ' igrnstr];
disp(message);
    
grainmeshfilename =  [nepermeshname '_' 'meshfile_grn_' num2str(igrn) ];   
load(grainmeshfilename);

US = meshfile1X.US;
USmodes = US(:,[1:nummodes]);

% Set mesh size variables from mesh coordinate and connectivity arrays
[m n]   = size(meshfile1X.crd);
numnp = n;

[m n]   = size(meshfile1X.con);
numel = n;

np = meshfile1X.con';
coords = meshfile1X.crd;

%
%define local variables for coordinates
%
    
x = coords(1,:)';
y = coords(2,:)';
z = coords(3,:)';

npcrossref = meshfile1X.npcrossref;

Fsr=zeros(numel*nnpe,1); 
Fsv=zeros(numel*nnpe,1); 

Ksr=zeros(numel*nnpe*nnpe,1); 
Ksc=zeros(numel*nnpe*nnpe,1); 
Ksv=zeros(numel*nnpe*nnpe,1);

Jsr=zeros(numel*nnpe*nnpe,1); 
Jsc=zeros(numel*nnpe*nnpe,1); 
Jsv=zeros(numel*nnpe*nnpe,1);

fc=1; 
kc=1;
jc=1;
 
fe= zeros(nnpe,1);
se = zeros(nnpe,nnpe);

element_volumes = zeros(1,numel);

%
for   iele =1:1:numel
    
  [dndx,dndy,dndz,detj,elvolume] = SFDerivatives(iele,nnpe,nqptv,wtqp,np,x,y,z,dndxi,dndet,dndze);

  element_volumes(iele) = elvolume;
  
  bigNprime = BigNprimeMat(nnpe,nqptv,dndx,dndy,dndz);
  
  me = ElementLHS4ConMass(nnpe,nqptv,wtqp,sfac,detj);

  [Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc] = AssembleSparseLaplace(iele,nnpe,np,se,me,fe,Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc);

end

 grain_weight = sum(element_volumes);
 grain_volumes(igrn) = grain_weight;

%
% Define sparse matrices and clean up
%

 mk=sparse(Jsr,Jsc,Jsv);
 mk = (mk+mk')/2;

 clear Frr Fsv Ksr Ksc Ksv Jsr Jsc Jsv;

fieldnpave = zeros(ncomp,numnp);
beta_matrix_orth = zeros(numframes,ncomp,nummodes);
beta_matrix_opt = zeros(numframes,ncomp,nummodes);

fieldnpavevector = zeros(ncomp*numnp,1);

%    loop over grains to evaluate beta array  -- follow process in
%    MechHarmonics to use every grain's individual mesh.
    
 for iframe = 1:1:numframes   

    framenumber=['/Frame_' num2str(iframe)];
    dataname = append(framenumber,'/');
    dataname = append(dataname,fieldvariablename);
    fielddata = h5read([framefilebasename '.h5'],dataname);
     
    for icomp = 1:1:ncomp         
        for inp = 1:1:numnp
        itarget = npcrossref(inp);
        fieldnpave(icomp,inp) = fielddata(icomp,itarget);
        end
    end

    %  evaluate beta values for orthogonality method

      dum = fieldnpave*mk*USmodes;  

      beta_matrix_orth(iframe,:,:) = dum(:,:); 
      beta_all_orth(iframe,:,:,igrn) = beta_matrix_orth(iframe,:,:);

    %  evaluate field variable using expansion with beta values from the
    %  orthogonality method

    field_frame_orth = zeros(ncomp,numnp);
    for imode = 1:1:nummodes 
        for jcomp=1:1:ncomp
            for knp = 1:1:numnp
            field_frame_orth(jcomp,knp) = field_frame_orth(jcomp,knp) + beta_all_orth(iframe,jcomp,imode,igrn)*US(knp,imode);
            end
        end
    end

   % save values

    for jcomp=1:1:ncomp
     for inp = 1:1:numnp
       itarget = npcrossref(inp);
       field_modes_orth(iframe,jcomp,itarget) = field_frame_orth(jcomp,inp);
       field_data(iframe,jcomp,itarget)  = fieldnpave(jcomp,inp);
     end
    end


    %  compute the grain average values using the first mode

    for jcomp =1:1:6
        field_grnave(iframe,jcomp,igrn) = beta_all_orth(iframe,jcomp,1,igrn)*US(1,1);
    end

    %  compute expansion errors

   field_diff_orth = zeros(6,numnp);
   field_error_orth = zeros(6,1);
   field_magnitude = zeros(numnp,1);

   for jcomp = 1:1:6
     field_diff_orth(jcomp,:) = field_frame_orth(jcomp,:)-fieldnpave(jcomp,:); 
     field_error_orth(jcomp) = sqrt(field_diff_orth(jcomp,:)*field_diff_orth(jcomp,:)');
   end

   for jnp = 1:1:numnp
     field_magnitude(jnp) = sqrt(fieldnpave(:,jnp)'*fieldnpave(:,jnp));
   end

   fieldnorm = sqrt(field_magnitude'*field_magnitude);

   field_error_norm_orth = norm(field_error_orth)/fieldnorm;
   error_all_orth(iframe,igrn) = field_error_norm_orth;

end
 
end

vector_size = 6*nummodes*ngrains;
beta_vector = zeros(vector_size,1);
ictr = 0;

for iframe = 1:1:numframes
    betavectorfilename =  [nepermeshname '_' 'betavector4mechrecon_frame_' num2str(iframe) ]; 

 for igrn  = 1:1:ngrains
  for icomp = 1:1:6
    for imode = 1:1:nummodes
        ictr = ictr+1;
        beta_vector(ictr) = beta_all_orth(iframe,icomp,imode,igrn);
    end
  end
 end 

save([betavectorfilename '.mat'],'beta_vector');
end


status = ' Finished all grains; begin writing plotting files ' 
    
outputfilename = input('Base name of output file names: ', 's');
    
    
save([outputfilename '_field_grnave.mat'],'field_grnave');


% Add results for all modes for all grains

harmonicfitfile    = Data_Structure_HarmonicFits(field_data,field_modes_orth,beta_all_orth,error_all_orth);

save([outputfilename '_fieldfits.mat'],'harmonicfitfile');

SUF = 'vtk';

file_harmonicfits_VTK = fopen(sprintf('%s.%s', [outputfilename '_fieldfits'], SUF), 'w');


Export_HarmonicFits_VTK(file_harmonicfits_VTK, harmonicfitfile , meshfilegbg,  phases,grains,numframes);

status = 'Completed writing results to VTK file'


end
